INSERT INTO _fleet_sync_outbox_items(item_id,live,payload_bytes,settlement_bytes,record,payload,capacity_slot) VALUES(?1,CAST(?2 AS INTEGER),CAST(?3 AS INTEGER),CAST(?4 AS INTEGER),?5,?6,CAST(?7 AS INTEGER)) ON CONFLICT(item_id) DO UPDATE SET capacity_slot=excluded.capacity_slot,live=excluded.live,payload_bytes=excluded.payload_bytes,settlement_bytes=excluded.settlement_bytes,record=excluded.record,payload=excluded.payload;
